<template><div class="page"><div class="page-header"><h2>通知记录</h2><div class="filter-bar"><el-select v-model="filter.channel" placeholder="渠道" clearable size="small" style="width:120px" @change="doSearch"><el-option v-for="c in channels" :key="c.channel" :label="c.label" :value="c.channel"/></el-select><el-select v-model="filter.send_status" placeholder="发送状态" clearable size="small" style="width:120px" @change="doSearch"><el-option label="未发" value="pending"/><el-option label="已发" value="sent"/><el-option label="失败" value="failed"/></el-select><el-input v-model="filter.ref_type" placeholder="关联类型" clearable size="small" style="width:120px" @keyup.enter="doSearch"/><el-input v-model="filter.ref_id" placeholder="关联ID" clearable size="small" style="width:140px" @keyup.enter="doSearch"/><el-button type="primary" size="small" @click="doSearch">查询</el-button><el-button size="small" @click="doReset">重置</el-button></div></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="openDetail"><el-table-column prop="template_id" label="模板ID" width="100"/><el-table-column prop="recipient" label="接收方" width="140"/><el-table-column label="渠道" width="70"><template #default="{row}"><el-tag size="small">{{ row.channel }}</el-tag></template></el-table-column><el-table-column prop="ref_type" label="关联类型" width="100"/><el-table-column prop="ref_id" label="关联ID" width="100"/><el-table-column label="发送状态" width="90"><template #default="{row}"><el-tag :type="sendStatusTag(row.send_status)" size="small">{{ row.send_status||'pending' }}</el-tag></template></el-table-column><el-table-column label="已读" width="70"><template #default="{row}"><el-tag v-if="row.channel==='internal'" :type="row.read_status==='read'?'success':'info'" size="small">{{ row.read_status==='read'?'已读':'未读' }}</el-tag><span v-else>-</span></template></el-table-column><el-table-column prop="send_time" label="发送时间" width="110"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button v-if="row.send_status!=='sent'" type="primary" link size="small" @click.stop="handleSend(row)">发送</el-button><el-button v-if="row.send_status==='failed'" type="warning" link size="small" @click.stop="handleSend(row)">重试</el-button><el-button v-if="row.channel==='internal'&&row.send_status==='sent'&&row.read_status!=='read'" type="success" link size="small" @click.stop="handleRead(row)">标为已读</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'通知详情'" v-model="drawer" width="600px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="模板ID">{{ detail.template_id||'-' }}</el-descriptions-item><el-descriptions-item label="渠道">{{ detail.channel }}</el-descriptions-item><el-descriptions-item label="接收方">{{ detail.recipient }}</el-descriptions-item><el-descriptions-item label="发送状态"><el-tag :type="sendStatusTag(detail.send_status)" size="small">{{ detail.send_status||'pending' }}</el-tag></el-descriptions-item><el-descriptions-item label="关联类型">{{ detail.ref_type||'-' }}</el-descriptions-item><el-descriptions-item label="关联ID">{{ detail.ref_id||'-' }}</el-descriptions-item><el-descriptions-item label="发送时间">{{ detail.send_time||'-' }}</el-descriptions-item><el-descriptions-item label="重试次数">{{ detail.retry_count||0 }}</el-descriptions-item><el-descriptions-item label="错误信息" :span="2">{{ detail.error_msg||'无' }}</el-descriptions-item><el-descriptions-item label="主题" :span="2">{{ detail.subject||'-' }}</el-descriptions-item><el-descriptions-item label="正文" :span="2"><div class="notif-body">{{ detail.body||'-' }}</div></el-descriptions-item></el-descriptions><div style="margin-top:12px"><strong>标题:</strong><p style="margin-top:4px;color:#303133">{{ detail.subject||'-' }}</p></div><div style="margin-top:12px"><strong>正文:</strong><pre style="background:#f5f7fa;padding:12px;border-radius:4px;margin-top:8px;white-space:pre-wrap;font-size:13px">{{ detail.body||'-' }}</pre></div></template><template #footer><el-button v-if="detail&&detail.send_status!=='sent'" type="primary" @click="handleSend(detail)">发送</el-button><el-button @click="drawer=false">关闭</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {ref,reactive,onMounted} from 'vue';import {useRoute} from 'vue-router';import {ElMessage} from 'element-plus';import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchNotifications,sendNotification,markNotificationRead,fetchChannels} from '@/api/notification';import type {NotifRecord,ChannelInfo} from '@/api/notification'
const route=useRoute()
const channels=ref<ChannelInfo[]>([])
const{items,loading,page,perPage,total,onSearch}=useListPage<NotifRecord>(fetchNotifications);const{drawer,detail,open}=useDetailDrawer<NotifRecord>()
onMounted(async()=>{try{const res=await fetchChannels();channels.value=res.data.channels}catch{channels.value=[]}})
const filter=reactive({channel:'',send_status:'',ref_type:'',ref_id:''})
function sendStatusTag(s:unknown){const m:Record<string,string>={pending:'info',sent:'success',failed:'danger'};return m[String(s)]||'info'}
function buildParams():Record<string,string>{const p:Record<string,string>={};if(filter.channel)p.channel=filter.channel;if(filter.send_status)p.send_status=filter.send_status;if(filter.ref_type)p.ref_type=filter.ref_type;if(filter.ref_id)p.ref_id=filter.ref_id;return p}
function doSearch(){onSearch(buildParams())}
function doReset(){filter.channel='';filter.send_status='';filter.ref_type='';filter.ref_id='';onSearch({})}
async function handleSend(row:NotifRecord){const id=row.notification_id as number;if(!id)return;try{await sendNotification(id);ElMessage.success('发送成功');doSearch()}catch{ElMessage.error('发送失败')}}
async function handleRead(row:NotifRecord){const id=row.notification_id as number;if(!id)return;try{await markNotificationRead(id);ElMessage.success('已标记为已读');doSearch()}catch{ElMessage.error('操作失败')}}
function openDetail(row:NotifRecord){open(row);if(row.channel==='internal'&&row.send_status==='sent'&&row.read_status!=='read'){handleRead(row)}}
onMounted(()=>{const q=route.query;if(q.ref_type)filter.ref_type=String(q.ref_type);if(q.ref_id)filter.ref_id=String(q.ref_id);if(q.send_status)filter.send_status=String(q.send_status);doSearch();if(q.action==='edit'||q.action==='create'){setTimeout(()=>{if(items.value.length>0)openDetail(items.value[0])},300)}})
</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:8px}.page-header h2{font-size:18px;font-weight:600;margin:0}.filter-bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}</style>
